<?php
header('Content-Type: application/json; charset=utf-8');
$pdo=new PDO('mysql:host=localhost;dbname=testorder;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
try{$pdo->exec("CREATE TABLE IF NOT EXISTS order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,product_id INT UNSIGNED NULL,service_id INT UNSIGNED NULL,title VARCHAR(255) NOT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,quantity INT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$method=$_SERVER['REQUEST_METHOD'];if($method==='GET'){$id=(int)($_GET['order_id']??0);$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$s->execute([$id]);echo json_encode($s->fetchAll(),JSON_UNESCAPED_UNICODE);exit;}if($method==='DELETE'){ $id=(int)($_GET['id']??0);$pdo->prepare('DELETE FROM order_items WHERE id=?')->execute([$id]);echo json_encode(['status'=>'success']);exit;}$d=json_decode(file_get_contents('php://input'),true)?:$_POST;$order=(int)($d['order_id']??0);$product=(int)($d['product_id']??0);$service=(int)($d['service_id']??0);$qty=max(1,(int)($d['quantity']??1));if(!$order||(!$product&&!$service))throw new RuntimeException('Выберите товар или услугу');if($product){$s=$pdo->prepare('SELECT name,price FROM products WHERE id=?');$s->execute([$product]);$x=$s->fetch();}else{$s=$pdo->prepare('SELECT name,price FROM services WHERE id=?');$s->execute([$service]);$x=$s->fetch();}if(!$x)throw new RuntimeException('Позиция не найдена');$price=is_numeric($x['price'])?(float)$x['price']:0;$s=$pdo->prepare('INSERT INTO order_items(order_id,product_id,service_id,title,price,quantity) VALUES(?,?,?,?,?,?)');$s->execute([$order,$product?:null,$service?:null,$x['name'],$price,$qty]);echo json_encode(['status'=>'success','id'=>$pdo->lastInsertId()],JSON_UNESCAPED_UNICODE);}catch(Throwable $e){http_response_code(400);echo json_encode(['status'=>'error','message'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}